# ENGINE — identical in every retrospective; everything above is dated facts.
# FROZEN RULES (retro method r2): scenario inputs are derived from the facts
# above, never chosen by hand, so no later knowledge can enter through them.
# Analog semiconductor sibling of acn_engine.py.tmpl (via the LOW, AAPL and NKE
# engines): rules R1-R5, scoring, robustness and export are the same; the signals,
# the segment bridge, the EPS check and the report wording differ, and the listing
# and short-history rules below apply where the history is too short to measure.
# ═════════════════════════════════════════════════════════════════════════════
import math

def _cagr(a, b, years):
    return (b / a) ** (1 / years) - 1

def _median(v):
    v = sorted(v); n = len(v)
    return v[n // 2] if n % 2 else (v[n // 2 - 1] + v[n // 2]) / 2

def _pct_range(lo, hi):
    return f"{lo:+g}%" if lo == hi else f"+{lo:g}-{hi:g}%" if lo >= 0 else f"{lo:+g}% to {hi:+g}%"   # "+6%", "+6-7%", "-1% to +1%"

def _ordinal(n):
    return f"{n}{'th' if 10 <= n % 100 <= 20 else {1: 'st', 2: 'nd', 3: 'rd'}.get(n % 10, 'th')}"

def _now(v, u):
    return "n/r" if v is None else f"{v:+.1f}{u}"

def _usd(v):
    return f"${v:.2f}" if v >= 0 else f"$({-v:.2f})"    # a loss per share in parentheses, as the filings print it

# Short history (the bounds rule, retro/README.md "AVGO"): a listing in 2009 with a history that starts after the loss years
# leaves too few years for some rules; where a rule cannot be measured, its own bound stands: BEAR's 0% cap, BULL's BASE
# floor, XBULL's BULL floor, no net buyback, a neutral growth factor, a flat bridge. With enough years each line is r2's.
_FY = sorted(EPS_NORM)     # a year excluded from the history (a distorted year, method r2) leaves a gap: growth is measured
                            # only between years in it (one-year changes between consecutive years, two-year runs between two)
EPS_YOY           = [EPS_NORM[y] / EPS_NORM[y - 1] - 1 for y in _FY[1:] if y - 1 in EPS_NORM]
_RY               = sorted(REVENUE_HIST)
REV_YOY           = [REVENUE_HIST[y] / REVENUE_HIST[y - 1] - 1 for y in _RY[1:] if y - 1 in REVENUE_HIST]
REV_MEDIAN_GROWTH = _median(REV_YOY) if REV_YOY else None                          # median revenue growth over the history
REV_CAGR_10Y      = _cagr(REVENUE_HIST[_RY[0]], REVENUE_HIST[_RY[-1]], _RY[-1] - _RY[0]) if len(_RY) > 1 else 0.0
MARGIN_CONTRIB    = (FY_MARGIN_BASE - PREV_FY_MARGIN) / FY_MARGIN_BASE if MARGIN_GUIDED else 0.0   # guided margin step, as EPS growth
_SY               = sorted(SHARES_HIST)
BUYBACK           = _cagr(SHARES_HIST[_SY[-1]], SHARES_HIST[_SY[0]], _SY[-1] - _SY[0]) if len(_SY) > 1 else 0.0
FWD_MID           = sum(FWD_GUIDE) / 2 / 100                                         # forward revenue growth (guide, else latest quarter)
_SPAN             = f"FY{_FY[0] % 100:02d}-FY{_FY[-1] % 100:02d}" + "".join(f" ex-FY{y % 100:02d}" for y in range(_FY[0], _FY[-1]) if y not in EPS_NORM)
_CAGR_ALL         = _cagr(EPS_NORM[_FY[0]], EPS_NORM[_FY[-1]], _FY[-1] - _FY[0]) if len(_FY) > 1 else None
_RUNS             = [_cagr(EPS_NORM[y - 2], EPS_NORM[y], 2) for y in _FY[1:] if y - 2 in EPS_NORM]   # runs whose ends are both in it

# R1  scenario EPS growth, current FY -> FY+2 (per year)
SCENARIO_CAGR = {
    "BEAR":  min([0.0] + EPS_YOY),                                      # worst year of the history, capped at 0
    "BASE":  FWD_MID + MARGIN_CONTRIB + BUYBACK,                        # latest forward guide carried forward
    "BULL":  _CAGR_ALL if _CAGR_ALL is not None else -math.inf,          # EPS CAGR over the history (none: BASE's, below)
    "XBULL": max(_RUNS) if _RUNS else -math.inf,                         # best 2-yr run of the history (none: BULL's, below)
}
SCENARIO_CAGR["BULL"]  = max(SCENARIO_CAGR["BULL"], SCENARIO_CAGR["BASE"])
SCENARIO_CAGR["XBULL"] = max(SCENARIO_CAGR["XBULL"], SCENARIO_CAGR["BULL"])
SCENARIO_EPS = {k: round(EPP_TODAY_EPS * (1 + g) ** 2, 2) for k, g in SCENARIO_CAGR.items()}
# R2  scenario P/E = percentile band of the stock's own P/E over the window (up to 10 yr; from the listing, the listing rule)
SCENARIO_PE  = {"BEAR": PE_PCTL["p10"], "BASE": PE_PCTL["median"], "BULL": PE_PCTL["p75"], "XBULL": PE_PCTL["p90"]}
SCENARIO_TXT = {
    "BEAR":  (f"EPS {SCENARIO_CAGR['BEAR']*100:+.1f}%/yr (worst year {_SPAN}, capped at 0%); P/E to its 10th pct" if EPS_YOY else
              f"Flat EPS (no EPS change in {_SPAN} to measure: the 0% cap); P/E to its 10th pct"),
    "BASE":  f"EPS {SCENARIO_CAGR['BASE']*100:+.1f}%/yr ({FWD_BASIS_SHORT} + margin + buyback); P/E at its {WINDOW_LABEL} median",
    "BULL":  (f"EPS {SCENARIO_CAGR['BULL']*100:+.1f}%/yr ({_SPAN} CAGR, at least BASE); P/E holds its 75th pct" if _CAGR_ALL is not None else
              f"EPS {SCENARIO_CAGR['BULL']*100:+.1f}%/yr (no {_SPAN} CAGR to measure: BASE's rate); P/E holds its 75th pct"),
    "XBULL": (f"EPS {SCENARIO_CAGR['XBULL']*100:+.1f}%/yr (best 2-yr run {_SPAN}, at least BULL); P/E at its 90th pct" if _RUNS else
              f"EPS {SCENARIO_CAGR['XBULL']*100:+.1f}%/yr (no 2-yr run in {_SPAN}: BULL's rate); P/E at its 90th pct"),
}
# R3  EPP floor P/E = median of the calendar-year P/E lows, rounded down
EPP_MIN_PE = float(math.floor(_median([pe for _, pe, _ in YEARLY_MIN_PE])))
# R4  structural factors: valuation and growth are mechanical, the rest are constant across dates
PE_NOW          = CURRENT_PRICE / EPP_TODAY_EPS
